<template><q-page class="bg-simulator text-white row justify-center q-pa-xl"><q-card class="tool public-profile"><q-card-section><div class="text-h5 text-weight-bold">Perfil compartilhado</div><div class="text-caption text-grey-5">Somente informações autorizadas pelo titular.</div></q-card-section><q-separator dark /><q-card-section v-if="loading" class="row justify-center q-pa-xl"><q-spinner color="primary" size="38px" /></q-card-section><q-banner v-else-if="error" class="bg-red-9 text-white">{{ error }}</q-banner><q-card-section v-else><div class="text-h6">{{ profile.displayName || profile.primaryName || 'Perfil' }}</div><q-list dark separator class="q-mt-md"><q-item v-for="item in fields" :key="item.label"><q-item-section><q-item-label caption class="text-grey-5">{{ item.label }}</q-item-label><q-item-label>{{ item.value }}</q-item-label></q-item-section></q-item></q-list></q-card-section></q-card></q-page></template>
<script setup>
import { computed, ref } from "vue"; import { useRoute } from "vue-router"; import { getPublicProfile } from "src/services/clientMediaService"; import { getApiErrorMessage } from "src/services/clientAuthService";
const route=useRoute(),loading=ref(true),error=ref(""),profile=ref({});const fields=computed(()=>Object.entries(profile.value||{}).filter(([key,value])=>value!=null&&typeof value!=="object"&&!/[Tt]oken|secret|password|evidence/.test(key)&&!['displayName','primaryName'].includes(key)).map(([key,value])=>({label:key,value})));
const load=async()=>{try{profile.value=await getPublicProfile(route.params.token)}catch(e){error.value=getApiErrorMessage(e,"Este link é inválido, expirou ou foi revogado.")}finally{loading.value=false}};load();
</script><style scoped>.public-profile{width:min(720px,100%);align-self:flex-start}</style>
